        "descriptionFromSource": "From tummy time and activity center to child table and chair – this activity center features 5 modes of use! Grows with your baby, supporting development from birth to 36 months. Created with love and care under the guidance of pediatric physical therapists, this activity center promotes essential skills from day one with over 20 activities and 6 developmental toys. 360-degree rotating swivel & bounce seat allows babies to safely explore from every angle. Features a take-along piano with lights & sounds, month-by-month milestone cards and an adorable design.",
